# name: lag1_rating_agreement
# description: Proportion of consecutive trials (trial_index increasing by 1, same set) with the same yes/no answer; observed above the null means sequential response perseveration (or per-set stickiness) the trial-independent model lacks, below means alternation.
def test_statistic(df):
    ti = df["trial_index"].values
    r = df["rating"].values
    s = df["number_set"].astype(str).values
    m = (ti[1:] == ti[:-1] + 1) & (s[1:] == s[:-1])
    if m.sum() == 0:
        return 0.0
    return float((r[1:][m] == r[:-1][m]).mean())

# name: far_target_yes_rate
# description: Yes rate for targets more than 30 away from every example; observed above the model's null means people say yes to remote targets more than the model's concepts (plus noise) allow, i.e. a baseline lapse/guess rate is missing.
def test_statistic(df):
    ex = df["number_set"].astype(str).str.split(",", expand=True).apply(pd.to_numeric, errors="coerce").values
    t = df["target"].astype(float).values[:, None]
    d = np.nanmin(np.abs(ex - t), axis=1)
    m = d > 30
    if m.sum() == 0:
        return 0.0
    return float(df["rating"].values[m].mean())

# name: target_in_set_yes_rate
# description: Yes rate on trials whose target is one of the shown examples; observed below the model's null means the model is over-confident (lacks lapses/doubt) on exact example targets.
def test_statistic(df):
    ex = df["number_set"].astype(str).str.split(",", expand=True).apply(pd.to_numeric, errors="coerce").values
    t = df["target"].astype(float).values[:, None]
    m = (ex == t).any(axis=1)
    if m.sum() == 0:
        return 0.0
    return float(df["rating"].values[m].mean())

# name: trial_index_late_minus_early
# description: Yes rate on trials with trial_index >= 225 minus yes rate on trials < 225; the model has no drift, so observed far from the null means responding to identical stimuli changes over the session (negative = growing conservatism).
def test_statistic(df):
    ti = df["trial_index"].values
    r = df["rating"].values.astype(float)
    a = ti >= 225; b = ti < 225
    if a.sum() == 0 or b.sum() == 0:
        return 0.0
    return float(r[a].mean() - r[b].mean())
